package com.crm.invoice.service;
import com.crm.invoice.entity.*;import com.crm.invoice.repository.*;import com.crm.invoice.pdf.PdfReport;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.data.domain.Page;import jakarta.validation.constraints.*;import java.util.*;import java.math.BigDecimal;
@Service @Transactional public class InvoicePresentationService {private final InvoicePresentationRepository templates;private final InvoiceRepository invoices;private final InvoiceDocumentRepository documents;private final InvoicePaymentRepository payments;@jakarta.persistence.PersistenceContext private jakarta.persistence.EntityManager em;public InvoicePresentationService(InvoicePresentationRepository t,InvoiceRepository i,InvoiceDocumentRepository d,InvoicePaymentRepository p){templates=t;invoices=i;documents=d;payments=p;}
 public record Input(@NotBlank @Size(max=100) String name,@NotBlank @Size(max=255) String header,@NotNull @Size(max=1000) String company,@NotNull @Size(max=1000) String footer,@NotNull @Size(max=1000) String mentions,@NotBlank @Pattern(regexp="COMPACT|DETAIL") String layout){}
 public record View(String id,String name,String header,String company,String footer,String mentions,String layout,boolean active,boolean used,boolean logo){}
 @Transactional(readOnly=true) public Page<View> list(int page){InvoiceWorkAccess.admin();return templates.findAll(InvoiceWorkAccess.page(page)).map(this::view);}
 public View save(Long id,Input input){InvoiceWorkAccess.admin();InvoiceWorkAccess.valid(input);var t=id==null?new InvoicePresentation():locked(id);if(t.isUsed())throw InvoiceWorkAccess.conflict();t.setName(input.name().trim());t.setHeader(input.header());t.setCompany(input.company());t.setFooter(input.footer());t.setMentions(input.mentions());t.setLayout(input.layout());return view(templates.saveAndFlush(t));}
 public View active(long id,boolean active){InvoiceWorkAccess.admin();var t=locked(id);t.setActive(active);return view(t);}
 public View logo(long id,byte[] data){InvoiceWorkAccess.admin();var t=locked(id);if(t.isUsed())throw InvoiceWorkAccess.conflict();t.setLogo(normalizeLogo(data));return view(t);}
 public byte[] normalizeLogo(byte[] data){if(data==null||data.length==0||data.length>262144)throw new IllegalArgumentException("Logo maximum 256 KiB");try(var input=javax.imageio.ImageIO.createImageInputStream(new java.io.ByteArrayInputStream(data))){var readers=javax.imageio.ImageIO.getImageReaders(input);if(!readers.hasNext())throw new IllegalArgumentException("PNG or JPEG required");var reader=readers.next();try{reader.setInput(input,true,true);if(!Set.of("png","jpeg","jpg").contains(reader.getFormatName().toLowerCase(Locale.ROOT))||reader.getWidth(0)>2000||reader.getHeight(0)>2000||(long)reader.getWidth(0)*reader.getHeight(0)>1000000)throw new IllegalArgumentException("Logo dimensions exceed limits");var image=reader.read(0);var out=new java.io.ByteArrayOutputStream();javax.imageio.ImageIO.write(image,"png",out);if(out.size()>262144)throw new IllegalArgumentException("Normalized logo exceeds limit");return out.toByteArray();}finally{reader.dispose();}}catch(java.io.IOException e){throw new IllegalArgumentException("Unreadable logo");}}
 @Transactional(readOnly=true) public byte[] preview(long id){InvoiceWorkAccess.admin();var t=templates.findById(id).orElseThrow(InvoiceWorkAccess::missing);var i=new Invoice();i.setInvoiceNumber("PREVISUALISATION");i.setCustomerId("Exemple");i.setSubtotal(new BigDecimal("100.00"));i.setTotalAmount(new BigDecimal("100.00"));i.setCurrency("DEV");i.setStatus("DRAFT");var line=new InvoiceLine();line.setDescription("Exemple de prestation");line.setQuantity(BigDecimal.ONE);line.setUnitPrice(new BigDecimal("100"));line.setLineTotal(new BigDecimal("100"));i.getLines().add(line);return render(i,t);}
 @Transactional(readOnly=true) public byte[] previewInvoice(long invoiceId,long templateId){InvoiceWorkAccess.admin();var i=invoices.findById(invoiceId).orElseThrow(InvoiceWorkAccess::missing);if(i.isIssued())return snapshot(invoiceId);return render(i,templates.findById(templateId).orElseThrow(InvoiceWorkAccess::missing));}
 public byte[] issue(long invoiceId,long templateId){long actor=InvoiceWorkAccess.admin();var i=invoices.lockById(invoiceId).orElseThrow(InvoiceWorkAccess::missing);refresh(i);if(i.isArchived())throw InvoiceWorkAccess.conflict();if(i.isIssued()){var d=documents.findById(invoiceId).orElseThrow(InvoiceWorkAccess::missing);if(d.getPresentationId()!=templateId)throw InvoiceWorkAccess.conflict();return verified(d);}if(!Set.of("DRAFT","PENDING","UNPAID").contains(i.getStatus())||payments.existsByInvoiceId(invoiceId))throw InvoiceWorkAccess.conflict();var t=locked(templateId);if(!t.isActive()||i.getIssueDate()==null||i.getDueDate()==null||i.getDueDate().isBefore(i.getIssueDate())||i.getCurrency()==null||!i.getCurrency().matches("[A-Z]{3}"))throw InvoiceWorkAccess.conflict();FinancialValidation.calculated(i.getTotalAmount());byte[] bytes=render(i,t);if(bytes.length>2*1024*1024)throw new IllegalArgumentException("Document exceeds technical limit");var d=new InvoiceDocument();d.setInvoiceId(invoiceId);d.setPresentationId(templateId);d.setContent(bytes);d.setDigest(digest(bytes));d.setCreatedBy(actor);documents.saveAndFlush(d);t.setUsed(true);i.setIssued(true);if(i.getStatus().equals("DRAFT"))i.setStatus("UNPAID");return bytes;}
 @Transactional(readOnly=true) public byte[] snapshot(long id){var i=invoices.findById(id).orElseThrow(InvoiceWorkAccess::missing);if(!i.isIssued())return null;return verified(documents.findById(id).orElseThrow(InvoiceWorkAccess::missing));}
 private byte[] verified(InvoiceDocument d){if(!digest(d.getContent()).equals(d.getDigest()))throw new IllegalStateException("Document integrity failure");return d.getContent();}private String digest(byte[] value){try{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(value));}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 private byte[] render(Invoice i,InvoicePresentation t){List<PdfReport.Row> rows=new ArrayList<>();rows.add(new PdfReport.Row("En-tête",t.getHeader()));rows.add(new PdfReport.Row("Entreprise / coordonnées",t.getCompany()));rows.add(new PdfReport.Row("Numéro",i.getInvoiceNumber()));rows.add(new PdfReport.Row("Client (référence)",i.getCustomerId()));rows.add(new PdfReport.Row("Émission",PdfReport.date(i.getIssueDate())));rows.add(new PdfReport.Row("Échéance",PdfReport.date(i.getDueDate())));if(i.getLines().size()>100)throw new IllegalArgumentException("At most 100 document lines");for(var line:i.getLines()){rows.add(new PdfReport.Row(line.getDescription(),line.getQuantity().toPlainString()+" x "+PdfReport.amount(line.getUnitPrice(),i.getCurrency())+" = "+PdfReport.amount(line.getLineTotal(),i.getCurrency())));if(t.getLayout().equals("DETAIL"))rows.add(new PdfReport.Row("Détail quantité / taux",line.getQuantity().toPlainString()+" / "+line.getUnitPrice().toPlainString()));}rows.add(new PdfReport.Row("Sous-total",PdfReport.amount(i.getSubtotal(),i.getCurrency())));rows.add(new PdfReport.Row("Taxe saisie",PdfReport.amount(i.getTax(),i.getCurrency())));rows.add(new PdfReport.Row("Total enregistré",PdfReport.amount(i.getTotalAmount(),i.getCurrency())));rows.add(new PdfReport.Row("Mentions",t.getMentions()));rows.add(new PdfReport.Row("Pied de page",t.getFooter()));return PdfReport.renderWithLogo("Facture",i.getInvoiceNumber(),rows,t.getLogo());}
 private InvoicePresentation locked(long id){var t=templates.lock(id).orElseThrow(InvoiceWorkAccess::missing);refresh(t);return t;}private void refresh(Object r){if(em!=null)em.refresh(r,jakarta.persistence.LockModeType.PESSIMISTIC_WRITE);}private View view(InvoicePresentation t){return new View(t.getId().toString(),t.getName(),t.getHeader(),t.getCompany(),t.getFooter(),t.getMentions(),t.getLayout(),t.isActive(),t.isUsed(),t.getLogo()!=null);}
}
